package com.mint.rebuilt;
import android.app.Activity;
import android.content.Context;
import java.io.*;
import org.json.*;
public final class ConfigNative {
 private static final String DEFAULT="{\"usernameEnabled\":true,\"usernameLength\":15,\"usernameAlphanumeric\":true,\"passwordEnabled\":true,\"password\":\"\",\"pinEnabled\":true,\"pin\":\"\",\"historyEnabled\":true,\"historyRounds\":10,\"wagerEnabled\":true,\"proxyEnabled\":false,\"proxyProtocol\":\"http\",\"proxyHost\":\"\",\"proxyPort\":0,\"proxyUsername\":\"\",\"proxyPassword\":\"\"}";
 private static File file(Context c){File root=new File(c.getApplicationInfo().dataDir,".mint_mod_state");if(!root.exists()&&!root.mkdirs())throw new IllegalStateException("Não foi possível abrir as configurações.");return new File(root,"config.json");}
 public static synchronized String json(Context c){try{File f=file(c);if(!f.isFile())return DEFAULT;ByteArrayOutputStream out=new ByteArrayOutputStream();FileInputStream in=new FileInputStream(f);try{byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>32768)throw new IOException();out.write(b,0,n);}}finally{in.close();}JSONObject defaults=new JSONObject(DEFAULT),v=new JSONObject(out.toString("UTF-8"));java.util.Iterator<String> keys=defaults.keys();while(keys.hasNext()){String key=keys.next();if(!v.has(key))v.put(key,defaults.get(key));}return v.toString();}catch(Exception e){return DEFAULT;}}
 public static synchronized boolean write(Context c,JSONObject next){File temp=null;try{File f=file(c);temp=new File(f.getParentFile(),"config.tmp");FileOutputStream out=new FileOutputStream(temp);try{out.write(next.toString().getBytes("UTF-8"));out.getFD().sync();}finally{out.close();}if(!temp.renameTo(f))throw new IOException();return true;}catch(Exception e){if(temp!=null)temp.delete();return false;}}
 public static boolean restoreDefaults(Activity a){return save(a,DEFAULT);}
 public static synchronized boolean save(Activity a,String text){try{JSONObject in=new JSONObject(text),old=new JSONObject(json(a)),next=new JSONObject();for(String key:new String[]{"usernameEnabled","usernameAlphanumeric","passwordEnabled","pinEnabled","historyEnabled","wagerEnabled"}){Object v=in.has(key)?in.get(key):old.get(key);if(!(v instanceof Boolean))return false;next.put(key,v);}for(String key:new String[]{"usernameLength","historyRounds"}){Object v=in.has(key)?in.get(key):old.get(key);if(!(v instanceof Integer))return false;int n=(Integer)v;if(n<1||n>(key.equals("usernameLength")?64:100))return false;next.put(key,n);}for(String key:new String[]{"password","pin"}){Object v=in.has(key)?in.get(key):old.get(key);if(!(v instanceof String)||((String)v).length()>1024)return false;if(key.equals("pin")&&!((String)v).isEmpty()&&!((String)v).matches("[0-9]{6}"))return false;next.put(key,v);}for(String key:new String[]{"proxyEnabled","proxyProtocol","proxyHost","proxyPort","proxyUsername","proxyPassword"})next.put(key,in.has(key)?in.get(key):old.get(key));ProxyConfig proxy=ProxyConfig.fromJson(next),before=ProxyConfig.fromJson(old);proxy.writeTo(next);if(!write(a,next))return false;if(!proxy.sameSettings(before)&&!BrowserProxy.apply(a,proxy.enabled)){before.writeTo(next);write(a,next);return false;}PortRuntime.changed();return true;}catch(Exception e){return false;}}
 public static String page(Context c,boolean game){try{JSONObject in=new JSONObject(json(c)),out=new JSONObject();for(String k:new String[]{"historyEnabled","historyRounds","wagerEnabled"})out.put(k,in.get(k));if(!game)for(String k:new String[]{"usernameEnabled","usernameLength","usernameAlphanumeric","passwordEnabled","password","pinEnabled","pin"})out.put(k,in.get(k));return out.toString().replace("<","\\u003c");}catch(Exception e){return "{}";}}
}
